const input = $input.first().json || {};
const body = input.body && typeof input.body === 'object' && !Array.isArray(input.body) ? input.body : input;
const errors = [];
const rawMode = body.mode;
const mode = rawMode === undefined || rawMode === null || rawMode === '' ? 'controle' : rawMode;

if (rawMode !== undefined && rawMode !== null && rawMode !== '' && mode !== 'controle' && mode !== 'creation') {
  errors.push({ field: 'mode', message: 'Le mode doit valoir controle ou creation.' });
}
if (body === null || typeof body !== 'object' || Array.isArray(body)) {
  errors.push({ field: 'body', message: 'Le corps doit etre un objet JSON.' });
}

const allowedRoot = ['mode', 'daty', 'codeetablissement', 'projet', 'designation', 'idcategorieachat', 'patrimoine', 'lignes'];
if (body && typeof body === 'object' && !Array.isArray(body)) {
  for (const key of Object.keys(body)) {
    if (!allowedRoot.includes(key)) errors.push({ field: key, message: 'Champ non autorise.' });
  }
}

const isText = (value) => typeof value === 'string' && value.trim().length > 0;
const isOptionalText = (value) => value === undefined || value === null || typeof value === 'string';
const isDate = (value) => typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) && !Number.isNaN(Date.parse(value));

if (!isDate(body.daty)) errors.push({ field: 'daty', message: 'Date invalide, format attendu AAAA-MM-JJ.' });
for (const key of ['codeetablissement', 'projet', 'designation']) {
  if (!isText(body[key])) errors.push({ field: key, message: 'Valeur texte non vide requise.' });
}
if (!isOptionalText(body.idcategorieachat)) errors.push({ field: 'idcategorieachat', message: 'Valeur texte ou null attendue.' });
if (!isOptionalText(body.patrimoine)) errors.push({ field: 'patrimoine', message: 'Valeur texte ou null attendue.' });

const lines = body.lignes;
if (!Array.isArray(lines) || lines.length < 1 || lines.length > 100) {
  errors.push({ field: 'lignes', message: 'Entre 1 et 100 lignes sont requises.' });
} else {
  const allowedLine = ['produit', 'designation', 'unite', 'qte', 'pu', 'remarque'];
  lines.forEach((line, index) => {
    const prefix = 'lignes[' + index + ']';
    if (!line || typeof line !== 'object' || Array.isArray(line)) {
      errors.push({ field: prefix, message: 'Ligne invalide.' });
      return;
    }
    for (const key of Object.keys(line)) {
      if (!allowedLine.includes(key)) errors.push({ field: prefix + '.' + key, message: 'Champ non autorise.' });
    }
    if (!isText(line.designation)) errors.push({ field: prefix + '.designation', message: 'Valeur texte non vide requise.' });
    if (!isText(line.unite)) errors.push({ field: prefix + '.unite', message: 'Valeur texte non vide requise.' });
    if (typeof line.qte !== 'number' || !Number.isFinite(line.qte) || line.qte <= 0) errors.push({ field: prefix + '.qte', message: 'Nombre strictement positif requis.' });
    if (typeof line.pu !== 'number' || !Number.isFinite(line.pu) || line.pu < 0) errors.push({ field: prefix + '.pu', message: 'Nombre positif ou nul requis.' });
    if (!isOptionalText(line.produit)) errors.push({ field: prefix + '.produit', message: 'Valeur texte ou null attendue.' });
    if (!isOptionalText(line.remarque)) errors.push({ field: prefix + '.remarque', message: 'Valeur texte ou null attendue.' });
  });
}

const payload = {
  daty: body.daty,
  codeetablissement: body.codeetablissement,
  projet: body.projet,
  designation: body.designation,
  lignes: body.lignes
};
if (Object.prototype.hasOwnProperty.call(body, 'idcategorieachat')) payload.idcategorieachat = body.idcategorieachat;
if (Object.prototype.hasOwnProperty.call(body, 'patrimoine')) payload.patrimoine = body.patrimoine;

return [{ json: { mode, payload, ok: errors.length === 0, errors } }];
